      event.res.errHeaders.set("content-type", "text/html");
      throw new HTTPError({ status: 400, message: "inválido" });
    });
    const res = await t.fetch("/");
    expect(res.headers.get("content-type")).toBe("application/problem+json");
  });

  it("renders an HTTPError returned by onError as problem details", async () => {
    enableProblemDetails();
    const onError = vi.fn(() => new HTTPError({ status: 503, message: "indisponível" }));
    t.app.config.onError = onError;
    t.app.get("/", () => {
      throw new Error("boom");
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(503);
    expect(res.headers.get("content-type")).toBe("application/problem+json");
    expect(await res.json()).toMatchObject({ detail: "indisponível" });
    expect(onError).toHaveBeenCalledTimes(1);
    t.errors = [];
  });

  it("keeps a plain object returned by onError as JSON", async () => {
    enableProblemDetails();
    t.app.config.onError = () => ({ ok: false });
    t.app.get("/", () => {
      throw new HTTPError({ status: 400, message: "inválido" });
    });
    const res = await t.fetch("/");
    expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
    expect(await res.text()).toBe('{"ok":false}');
  });

  it("does not duplicate errHeaders set-cookie when onError returns an HTTPError", async () => {
    enableProblemDetails();
    t.app.config.onError = () => new HTTPError({ status: 503, message: "indisponível" });
    t.app.get("/", (event) => {
      event.res.errHeaders.append("set-cookie", "a=1");
      throw new HTTPError({ status: 400, message: "inválido" });
    });
    const res = await t.fetch("/");
    expect(res.headers.getSetCookie()).toEqual(["a=1"]);
  });
});

describe("HTTPError type and instance", () => {
