      status: 400,
      cause: { type: "https://exemplo.com/erros/outro", instance: "/outro" },
    });
    expect(err.type).toBeUndefined();
    expect(err.instance).toBeUndefined();
  });

  it("copies type and instance when wrapping an HTTPError", () => {
    const original = new HTTPError({
      status: 403,
      type: "https://exemplo.com/erros/sem-saldo",
      instance: "/contas/42",
    });
