describe("problem details", () => {
  // The default test app runs in debug mode, which adds `stack` to every body
  const enableProblemDetails = () => {
    t.app.config.debug = false;
    t.app.config.problemDetails = true;
  };

  it("uses application/problem+json with the error status", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new HTTPError({ status: 404, message: "não encontrado" });
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(404);
    expect(res.headers.get("content-type")).toBe("application/problem+json");
    expect(await res.json()).toMatchObject({ status: 404, detail: "não encontrado" });
  });

  it("maps message to detail and statusText to title", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new HTTPError({
        status: 404,
        statusText: "Not Found",
        message: "Usuário não existe",
      });
    });
    const res = await t.fetch("/");
    expect(await res.text()).toBe(
      '{"type":"about:blank","title":"Not Found","status":404,"detail":"Usuário não existe"}',
    );
  });

  it("omits title when the error has no statusText", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new HTTPError({ status: 409, message: "conflito" });
    });
    const body = await (await t.fetch("/")).json();
    expect(body).not.toHaveProperty("title");
    expect(body).toMatchObject({ type: "about:blank", status: 409, detail: "conflito" });
  });

  it("renders type and instance, and omits instance when not set", async () => {
    enableProblemDetails();
    t.app.get("/with", () => {
      throw new HTTPError({
        status: 403,
        message: "sem saldo",
        type: "https://exemplo.com/erros/sem-saldo",
        instance: "/contas/42",
      });
    });
    t.app.get("/without", () => {
      throw new HTTPError({ status: 403, message: "sem saldo" });
    });

    const withIds = await (await t.fetch("/with")).json();
    expect(withIds).toMatchObject({
      type: "https://exemplo.com/erros/sem-saldo",
      instance: "/contas/42",
    });

    const withoutIds = await (await t.fetch("/without")).json();
    expect(withoutIds).toMatchObject({ type: "about:blank" });
    expect(withoutIds).not.toHaveProperty("instance");
  });

  it("keeps data and body at the root, with stack only in debug", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new HTTPError({
        status: 422,
        message: "inválido",
        data: { campo: "email" },
        body: { codigo: 7 },
      });
    });
    const text = await (await t.fetch("/")).text();
    expect(text).toContain('"data":{"campo":"email"}');
    expect(text).toContain('"codigo":7');
    expect(text).not.toContain("stack");

    t.app.config.debug = true;
    const body = await (await t.fetch("/")).json();
    expect(Array.isArray(body.stack)).toBe(true);
  });

  it("lets RFC members win over colliding body keys", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new HTTPError({
        status: 422,
        message: "ok",
        body: { status: 999, type: "x", detail: "y", title: "z", instance: "w" },
      });
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(422);
    const body = await res.json();
    expect(body).toMatchObject({ type: "about:blank", status: 422, detail: "ok" });
    expect(body).not.toHaveProperty("title");
    expect(body).not.toHaveProperty("instance");
  });

  it("does not leak unhandled error details", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new Error("senha do banco: 123");
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    expect(res.headers.get("content-type")).toBe("application/problem+json");
    const text = await res.text();
    expect(text).not.toContain("senha do banco");
    expect(JSON.parse(text)).toEqual({ type: "about:blank", status: 500 });
    t.errors = [];
  });

  it("ignores a type property on an unhandled error", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw Object.assign(new Error("bad json"), { type: "entity.parse.failed" });
    });
    const body = await (await t.fetch("/")).json();
    expect(body.type).toBe("about:blank");
    t.errors = [];
  });

  it("does not leak a thrown object", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw { secret: "db-password" };
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    expect(await res.text()).not.toContain("db-password");
    t.errors = [];
  });

  it("keeps error headers and sets the problem content-type", async () => {
    enableProblemDetails();
    t.app.get("/", () => {
      throw new HTTPError({
        status: 401,
        headers: { "www-authenticate": "Bearer", "content-type": "text/plain" },
      });
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(401);
    expect(res.headers.get("www-authenticate")).toBe("Bearer");
    expect(res.headers.get("content-type")).toBe("application/problem+json");
  });

  it("gives the problem content-type precedence over event.res.errHeaders", async () => {
    enableProblemDetails();
    t.app.get("/", (event) => {
      event.res.errHeaders.set("content-type", "text/html");
      throw new HTTPError({ status: 400, message: "inválido" });
    });
    const res = await t.fetch("/");
    expect(res.headers.get("content-type")).toBe("application/problem+json");
  });

  it("renders an HTTPError returned by onError as problem details", async () => {
    enableProblemDetails();
    const onError = vi.fn(() => new HTTPError({ status: 503, message: "indisponível" }));
    t.app.config.onError = onError;
    t.app.get("/", () => {
      throw new Error("boom");
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(503);
    expect(res.headers.get("content-type")).toBe("application/problem+json");
    expect(await res.json()).toMatchObject({ detail: "indisponível" });
    expect(onError).toHaveBeenCalledTimes(1);
    t.errors = [];
  });

  it("keeps a plain object returned by onError as JSON", async () => {
    enableProblemDetails();
    t.app.config.onError = () => ({ ok: false });
    t.app.get("/", () => {
      throw new HTTPError({ status: 400, message: "inválido" });
    });
    const res = await t.fetch("/");
    expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
    expect(await res.text()).toBe('{"ok":false}');
  });

  it("does not duplicate errHeaders set-cookie when onError returns an HTTPError", async () => {
    enableProblemDetails();
    t.app.config.onError = () => new HTTPError({ status: 503, message: "indisponível" });
    t.app.get("/", (event) => {
      event.res.errHeaders.append("set-cookie", "a=1");
      throw new HTTPError({ status: 400, message: "inválido" });
    });
    const res = await t.fetch("/");
    expect(res.headers.getSetCookie()).toEqual(["a=1"]);
  });
});

describe("HTTPError type and instance", () => {
  it("exposes type and instance", () => {
    const err = new HTTPError({
      status: 403,
      type: "https://exemplo.com/erros/sem-saldo",
      instance: "/contas/42",
    });
    expect(err.type).toBe("https://exemplo.com/erros/sem-saldo");
    expect(err.instance).toBe("/contas/42");
  });

  it("leaves type and instance undefined when omitted", () => {
    const err = new HTTPError({ status: 403 });
    expect(err.type).toBeUndefined();
    expect(err.instance).toBeUndefined();
  });

  it("treats non-string and empty values as absent", () => {
    const err = new HTTPError({ status: 400, type: 42 as any, instance: "" });
    expect(err.type).toBeUndefined();
    expect(err.instance).toBeUndefined();
  });

  it("does not inherit type or instance from cause", () => {
    const err = new HTTPError({
      status: 400,
      cause: { type: "https://exemplo.com/erros/outro", instance: "/outro" },
    });
    expect(err.type).toBeUndefined();
    expect(err.instance).toBeUndefined();
  });

  it("copies type and instance when wrapping an HTTPError", () => {
    const original = new HTTPError({
      status: 403,
      type: "https://exemplo.com/erros/sem-saldo",
      instance: "/contas/42",
    });
    const copy = new HTTPError(original);
    expect(copy.type).toBe(original.type);
    expect(copy.instance).toBe(original.instance);
  });

  it("keeps type and instance out of toJSON", () => {
    const err = new HTTPError({
      status: 403,
      type: "https://exemplo.com/erros/sem-saldo",
      instance: "/contas/42",
    });
    expect(err.toJSON()).not.toHaveProperty("type");
    expect(err.toJSON()).not.toHaveProperty("instance");
  });
});

