    ? problemBody(error, stack)
    : { ...error.toJSON(), stack };
  if (config.problemDetails) {
    // Set last so it wins over `content-type` coming from the error or `errHeaders`
    headers.set("content-type", "application/problem+json");
  }
  return new FastResponse(JSON.stringify(body, undefined, config.debug ? 2 : undefined), {
    status: error.status,
    statusText: error.statusText,
    headers,
  });
}

