import { build } from "esbuild";
import zlib from "node:zlib";

const targets = {
  H3Core: ["import { H3Core } from './src/index.ts'; new H3Core();", "./.baseline"],
  defineHandler: ["import { defineHandler } from './src/index.ts'; defineHandler({});", "./.baseline"],
};

for (const [name, [code, dir]] of Object.entries(targets)) {
  const root = dir === "./.baseline" ? "./.baseline" : ".";
  const entry = code.replace(/'\.\/src/g, `'${root}/src`);
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    stdin: { contents: entry, resolveDir: ".", sourcefile: "index.mjs", loader: "js" },
  });
  const bytes = res.outputFiles[0].contents.byteLength;
  const gzip = zlib.gzipSync(res.outputFiles[0].contents).byteLength;
  console.log(`${name} baseline/current=${root} bytes=${bytes} gzip=${gzip}`);
}

